/bin/bash -lc "python - <<'PY'
import json, urllib.parse, urllib.request
for repo in ['numpy','scipy','umap-learn','pandas']:
    print('---',repo)
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true'
    try:
      data=json.load(urllib.request.urlopen(url, timeout=30))
      for t in data.get('tags',[])[:20]: print(t['name'])
    except Exception as e: print(e)
PY"

